import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Zod Schema


export type MagicGradientTextProps = Record<string, any>;

const MagicGradientText: React.FC<MagicGradientTextProps> = ({
  text = "Magic out.",
  fontSize = 180,
  gradientStart = "#3b82f6", // Blue
  gradientMiddle = "#e879f9", // Pink/Purple
  gradientEnd = "#f97316", // Orange
  backgroundColor = "#050505",
  gridColor = "#ffffff",
  gridOpacity = 0.1,
  glowIntensity = 0.6,
  transparentBackground = false,
  durationInSeconds = 5,
}) => {
  // Load Fonts
  useFontLoader(["Outfit"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle Background Transparency
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Entrance Animation (Spring)
  const entrance = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  const opacity = interpolate(entrance, [0, 1], [0, 1]);
  const scale = interpolate(entrance, [0, 1], [0.8, 1]);
  const translateY = interpolate(entrance, [0, 1], [50, 0]);

  // Gradient Flow Animation
  // Moving the background position to create a shimmer effect
  const gradientPos = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [0, 200]
  );

  // Dynamic Styles
  const gradientStyle = {
    backgroundImage: `linear-gradient(90deg, ${gradientStart}, ${gradientMiddle}, ${gradientEnd}, ${gradientStart})`,
    backgroundSize: "200% auto",
    backgroundPosition: `${gradientPos}% center`,
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    backgroundClip: "text",
    color: "transparent", // Fallback
  };

  const gridStyle: React.CSSProperties = {
    backgroundImage: `radial-gradient(${gridColor} 1px, transparent 1px)`,
    backgroundSize: "40px 40px",
    opacity: gridOpacity,
    maskImage: "radial-gradient(circle at center, black 40%, transparent 100%)",
    WebkitMaskImage: "radial-gradient(circle at center, black 40%, transparent 100%)",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "'Outfit', sans-serif",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Grid with Vignette */}
      <AbsoluteFill style={gridStyle} />

      {/* Main Content Wrapper */}
      <div
        style={{
          position: "relative",
          fontSize: fontSize,
          fontWeight: 700,
          opacity,
          transform: `scale(${scale}) translateY(${translateY}px)`,
          textAlign: "center",
          width: "100%",
        }}
      >
        {/* Glow Layer (Blurry Duplicate behind) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundImage: `linear-gradient(90deg, ${gradientStart}, ${gradientMiddle}, ${gradientEnd}, ${gradientStart})`,
            backgroundSize: "200% auto",
            backgroundPosition: `${gradientPos}% center`,
            WebkitBackgroundClip: "text",
            backgroundClip: "text",
            WebkitTextFillColor: "transparent",
            filter: "blur(30px)",
            opacity: glowIntensity,
            zIndex: 0,
            paddingBottom: "0.2em", // Prevent clipping of blur
          }}
        >
          {text}
        </div>

        {/* Main Text Layer */}
        <div
          style={{
            position: "relative",
            zIndex: 1,
            ...gradientStyle,
          }}
        >
          {text}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MagicGradientText;